CREATE TABLE IF NOT EXISTS order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED NOT NULL,qty INT NOT NULL,price DECIMAL(14,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS jobs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,queue VARCHAR(100) NOT NULL DEFAULT 'default',name VARCHAR(150) NOT NULL,payload LONGTEXT NOT NULL,available_at TIMESTAMP NOT NULL,reserved_at TIMESTAMP NULL,attempts INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at TIMESTAMP NOT NULL,used_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS email_verifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at TIMESTAMP NOT NULL,verified_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webhooks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,provider VARCHAR(80) NOT NULL,event_id VARCHAR(180) NOT NULL,payload LONGTEXT NOT NULL,signature_valid TINYINT NOT NULL DEFAULT 0,processed_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_provider_event(provider,event_id));
CREATE TABLE IF NOT EXISTS api_rate_limits (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identifier VARCHAR(190) NOT NULL,window_start INT NOT NULL,requests INT NOT NULL DEFAULT 0,UNIQUE KEY uq_limit(identifier,window_start));
